param([int[]]$ProcessIds=@())
$ErrorActionPreference='Stop'
Add-Type -TypeDefinition @"
using System;using System.Runtime.InteropServices;using System.Collections.Generic;
public static class TonalAudioProbe {
 [ComImport,Guid("A95664D2-9614-4F35-A746-DE8DB63617E6"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Enumerator {[PreserveSig]int EnumAudioEndpoints(int f,uint s,out IntPtr d);[PreserveSig]int GetDefaultAudioEndpoint(int f,int r,out Device d);}
 [ComImport,Guid("D666063F-1587-4E43-81F1-B948E807363F"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Device {[PreserveSig]int Activate(ref Guid id,uint context,IntPtr parameters,[MarshalAs(UnmanagedType.IUnknown)]out object result);}
 [ComImport,Guid("77AA99A0-1BD6-484F-8BC7-2C654C9A9B6F"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Manager {[PreserveSig]int GetAudioSessionControl(IntPtr id,uint flags,out IntPtr control);[PreserveSig]int GetSimpleAudioVolume(IntPtr id,uint flags,out IntPtr volume);[PreserveSig]int GetSessionEnumerator(out Sessions sessions);}
 [ComImport,Guid("E2F5BB11-0570-40CA-ACDD-3AA01277DEE8"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Sessions {[PreserveSig]int GetCount(out int count);[PreserveSig]int GetSession(int index,[MarshalAs(UnmanagedType.IUnknown)]out object control);}
 [ComImport,Guid("bfb7ff88-7239-4fc9-8fa2-07c950be9c6d"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Session {
 [PreserveSig]int GetState(out int state);[PreserveSig]int GetDisplayName([MarshalAs(UnmanagedType.LPWStr)]out string name);[PreserveSig]int SetDisplayName([MarshalAs(UnmanagedType.LPWStr)]string value,IntPtr context);[PreserveSig]int GetIconPath([MarshalAs(UnmanagedType.LPWStr)]out string path);[PreserveSig]int SetIconPath([MarshalAs(UnmanagedType.LPWStr)]string value,IntPtr context);[PreserveSig]int GetGroupingParam(out Guid value);[PreserveSig]int SetGroupingParam(ref Guid value,IntPtr context);[PreserveSig]int RegisterAudioSessionNotification(IntPtr value);[PreserveSig]int UnregisterAudioSessionNotification(IntPtr value);[PreserveSig]int GetSessionIdentifier([MarshalAs(UnmanagedType.LPWStr)]out string value);[PreserveSig]int GetSessionInstanceIdentifier([MarshalAs(UnmanagedType.LPWStr)]out string value);[PreserveSig]int GetProcessId(out uint id);[PreserveSig]int IsSystemSoundsSession();[PreserveSig]int SetDuckingPreference(bool value);
 }
 [ComImport,Guid("C02216F6-8C67-4B5B-9D00-D008E73E0064"),InterfaceType(ComInterfaceType.InterfaceIsIUnknown)] interface Meter {[PreserveSig]int GetPeakValue(out float peak);[PreserveSig]int GetMeteringChannelCount(out int count);[PreserveSig]int GetChannelsPeakValues(int count,IntPtr values);[PreserveSig]int QueryHardwareSupport(out int mask);}
 public static object Read(int[] filter){var rows=new List<object>();object enumerator=null,manager=null;Device device=null;Sessions sessions=null;float endpointPeak=-1;
 try {enumerator=Activator.CreateInstance(Type.GetTypeFromCLSID(new Guid("BCDE0395-E52F-467C-8E3D-C4579291692E")));Marshal.ThrowExceptionForHR(((Enumerator)enumerator).GetDefaultAudioEndpoint(0,1,out device));Guid meterId=typeof(Meter).GUID;object endpointMeter=null;try{Marshal.ThrowExceptionForHR(device.Activate(ref meterId,23,IntPtr.Zero,out endpointMeter));((Meter)endpointMeter).GetPeakValue(out endpointPeak);}finally{if(endpointMeter!=null)Marshal.ReleaseComObject(endpointMeter);}
 Guid iid=typeof(Manager).GUID;Marshal.ThrowExceptionForHR(device.Activate(ref iid,23,IntPtr.Zero,out manager));((Manager)manager).GetSessionEnumerator(out sessions);int count;sessions.GetCount(out count);
 for(int i=0;i<count;i++){object control=null;try{sessions.GetSession(i,out control);var session=(Session)control;uint pid;int state;session.GetProcessId(out pid);session.GetState(out state);if(filter.Length>0&&Array.IndexOf(filter,(int)pid)<0)continue;float peak=-1;try{((Meter)control).GetPeakValue(out peak);}catch{}rows.Add(new {pid=pid,state=state,peak=peak});}finally{if(control!=null)Marshal.ReleaseComObject(control);}}
 }finally{if(sessions!=null)Marshal.ReleaseComObject(sessions);if(manager!=null)Marshal.ReleaseComObject(manager);if(device!=null)Marshal.ReleaseComObject(device);if(enumerator!=null)Marshal.ReleaseComObject(enumerator);}return new {endpointPeak=endpointPeak,sessions=rows.ToArray()};}
}
"@
ConvertTo-Json -InputObject @([TonalAudioProbe]::Read($ProcessIds)) -Depth 5 -Compress
